begin;
create or replace function internal.process_learner_event(target_event uuid,current_lease uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare e internal.outbox_events;r app.result_revisions;c app.activity_completions;a app.activities;p app.learner_state_policies;learner uuid;source_kind text;v_source_id uuid;obs uuid;start_at timestamptz;academic_rows jsonb;development_state jsonb;engagement_state jsonb;events uuid[];count_practice integer;count_reflection integer;ids_practice uuid[];ids_reflection uuid[];completed integer;last_completed timestamptz;signal_id uuid;
begin
 select *into e from internal.outbox_events where id=target_event for update;
 if not found or e.state<>'PROCESSING'or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()then raise exception 'Invalid event lease'using errcode='22023';end if;
 if exists(select 1 from internal.processed_events where event_id=e.id)then if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception 'Lease expired before acknowledgement'using errcode='22023';end if;return jsonb_build_object('status','DUPLICATE');end if;
 if e.type='result.released'then
  select *into r from app.result_revisions where school_id=e.school_id and id=e.entity_id;
  if not found or e.entity_type<>'result'or e.actor_id<>r.created_by or not exists(select 1 from app.academic_evidence ev where ev.school_id=r.school_id and ev.id=r.evidence_id and ev.result_id=r.id and ev.learner_id=r.learner_id and ev.source_object_id=r.submission_id)then raise exception 'Invalid released source'using errcode='22023';end if;
  learner:=r.learner_id;source_kind:='RESULT';v_source_id:=r.id;
 elsif e.type='activity.complete'then
  select *into c from app.activity_completions where school_id=e.school_id and id=e.entity_id;
  if not found or e.actor_id<>c.learner_id or e.entity_type<>'activity'then raise exception 'Invalid completion source'using errcode='22023';end if;
  select *into a from app.activities where school_id=c.school_id and id=c.activity_id;learner:=c.learner_id;source_kind:='COMPLETION';v_source_id:=c.id;
 elsif e.type in('course.create','course.publish','unit.create','lesson.create','activity.create','assessment.create','submission.create','reference.create','reference.approve','assessment.reference','assessment.marked','learner_state.updated','habit.observed','school.updated')then
  insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id);if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception 'Lease expired before acknowledgement'using errcode='22023';end if;return jsonb_build_object('status','ACKNOWLEDGED');
 else raise exception 'Unsupported domain event'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(e.school_id::text||':learner:'||learner::text,0));
 if exists(select 1 from internal.processed_events where school_id=e.school_id and source_type=source_kind and source_id=v_source_id)then insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id);if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception 'Lease expired before acknowledgement'using errcode='22023';end if;return jsonb_build_object('status','DUPLICATE_SOURCE');end if;
 if not exists(select 1 from app.schools where id=e.school_id and status='active')or not exists(select 1 from app.entitlements where school_id=e.school_id and code='learner.state'and enabled and effective_from<=now()and(effective_to is null or effective_to>now()))then raise exception 'Learner state policy unavailable'using errcode='42501';end if;
 select *into p from app.learner_state_policies where school_id=e.school_id;if not found then raise exception 'Approved development window required'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(e.school_id::text||':learner:'||learner::text,0));
 if source_kind='COMPLETION'and a.kind in('practice','reflection')then
  insert into app.habit_observations(school_id,learner_id,kind,source_object_id,occurred_at,source_event_id)values(e.school_id,learner,a.kind,c.id,c.completed_at,e.id)on conflict(school_id,source_object_id,kind)do nothing returning id into obs;
 end if;
 insert into internal.processed_events(event_id,school_id,source_type,source_id)values(e.id,e.school_id,source_kind,v_source_id);
 start_at:=clock_timestamp()-make_interval(days=>p.development_window_days);
 select coalesce(jsonb_agg(jsonb_build_object('resultId',rr.id,'referenceId',rr.reference_id,'referenceVersion',rr.reference_version,'nativeResult',jsonb_build_object('type','numeric','score',rr.score,'maxScore',rr.max_score,'policyVersion',rr.policy_version,'normalized',null),'evidenceId',rr.evidence_id,'observedAt',rr.created_at)order by rr.created_at),'[]'::jsonb)into academic_rows from app.current_results cr join app.result_revisions rr on rr.school_id=cr.school_id and rr.id=cr.result_id where cr.school_id=e.school_id and cr.learner_id=learner;
 select count(*)filter(where kind='practice'),count(*)filter(where kind='reflection'),coalesce(array_agg(id)filter(where kind='practice'),array[]::uuid[]),coalesce(array_agg(id)filter(where kind='reflection'),array[]::uuid[])into count_practice,count_reflection,ids_practice,ids_reflection from app.habit_observations where school_id=e.school_id and learner_id=learner and occurred_at>=start_at;
 select count(*),max(completed_at)into completed,last_completed from app.activity_completions where school_id=e.school_id and learner_id=learner;
 -- Counts reflect persisted records in an approved window, not psychological or attainment labels.
 development_state:=jsonb_build_object('completeness','RECORDED_ONLY','practice',jsonb_build_object('count',count_practice,'observationIds',ids_practice),'reflection',jsonb_build_object('count',count_reflection,'observationIds',ids_reflection),'revision',jsonb_build_object('count',null,'observationIds',array[]::uuid[]),'windowStart',start_at,'windowEnd',clock_timestamp());
 engagement_state:=jsonb_build_object('completedActivityCount',completed,'lastCompletedAt',last_completed);
 select coalesce(array_agg(event_id order by processed_at),array[]::uuid[])into events from internal.processed_events where school_id=e.school_id and source_type in('RESULT','COMPLETION')and((source_type='RESULT'and source_id in(select id from app.result_revisions where school_id=e.school_id and learner_id=learner))or(source_type='COMPLETION'and source_id in(select id from app.activity_completions where school_id=e.school_id and learner_id=learner)));
 if jsonb_array_length(academic_rows)>100 or cardinality(events)>1000 or cardinality(ids_practice)+cardinality(ids_reflection)>1000 or octet_length(academic_rows::text)+octet_length(development_state::text)>500000 then raise exception 'Learner projection requires bounded review'using errcode='22023';end if;
 insert into app.learner_state_snapshots(school_id,learner_id,version,academic,development,engagement,support,impact,source_event_ids)values(e.school_id,learner,1,academic_rows,development_state,engagement_state,'{"activeInterventionIds":[]}','{"status":"unmeasured","measurementIds":[]}',events)on conflict(school_id,learner_id)do update set version=app.learner_state_snapshots.version+1,generated_at=clock_timestamp(),academic=excluded.academic,development=excluded.development,engagement=excluded.engagement,source_event_ids=excluded.source_event_ids;
 if count_practice>0 then insert into app.learner_signals(school_id,learner_id,count,rule_version,window_start,window_end,source_event_ids,observation_ids)values(e.school_id,learner,count_practice,p.version,start_at,clock_timestamp(),events,ids_practice)on conflict(school_id,learner_id,type)do update set count=excluded.count,window_start=excluded.window_start,window_end=excluded.window_end,source_event_ids=excluded.source_event_ids,observation_ids=excluded.observation_ids,created_at=clock_timestamp()returning id into signal_id;end if;
 insert into internal.outbox_events(school_id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key)values(e.school_id,e.actor_id,'learner_state.updated','learner',learner,1,jsonb_build_object('learnerId',learner),'state:'||e.id::text)on conflict(school_id,deduplication_key)do nothing;
 if obs is not null then insert into internal.outbox_events(school_id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key)values(e.school_id,e.actor_id,'habit.observed','observation',obs,1,jsonb_build_object('learnerId',learner),'habit:'||e.id::text)on conflict(school_id,deduplication_key)do nothing;end if;
 if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception 'Lease expired before acknowledgement'using errcode='22023';end if;return jsonb_build_object('status','PROCESSED','learnerId',learner);
end$$;
commit;
